\title{Tropical Extremal-Support Profiles of Finitely Supported Rational
Sequences, with a Combinatorial-Species Corollary}
\author{Harmonic}
\date{2026-06-16}

\begin{document}
\maketitle

\begin{abstract}
We study the two extremal indices of a finitely supported rational sequence
$f \colon \N \to \Q$ --- its \emph{order} (the least index in the support) and its
\emph{degree} (the greatest index in the support) --- and prove that they form a
faithful pair of valuations into the tropical semiring. Under pointwise addition the
indices satisfy only the nonarchimedean inequalities
$\min(\ord f, \ord g) \le \ord(f+g)$ and $\deg(f+g) \le \max(\deg f, \deg g)$,
reflecting leading- and trailing-term cancellation. Under the Cauchy convolution they
add \emph{exactly}: $\ord(f * g) = \ord f + \ord g$ and $\deg(f * g) = \deg f + \deg g$.
Exactness rests on the \emph{unique extremal contributing pair} together with the fact
that $\Q$ is an integral domain. Carrying these laws across the exponential-generating-function
bridge of Joyal's theory of combinatorial species yields a corollary on the binomial
convolution: the minimal size of a structure built as the product of two species equals
the sum of the minimal sizes of the factors, and such a minimal structure provably exists.
We use the empty-support conventions $\ord 0 = \top$ and $\deg 0 = \bot$ in the
order-completions $\Nbar = \N \cup \{\top\}$ and $\Nbot = \N \cup \{\bot\}$.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
The two outermost terms of a polynomial --- its lowest- and highest-degree nonzero
monomials --- control a remarkable amount of its algebraic behaviour. The degree is the
most basic invariant of a polynomial ring; the order (valuation) is the most basic
invariant of a power-series ring or of a localization at a prime. Both are instances of
a single notion, the \emph{extremal support index}, and both are governed not by the
arithmetic of the coefficients but by the \emph{tropical} (min-plus / max-plus) arithmetic
of the indices.

This paper isolates that arithmetic in the cleanest setting --- finitely supported
sequences over a field --- proves the four governing laws (two inequalities for addition,
two equalities for convolution), and transports the order law across the
combinatorics-to-analysis dictionary supplied by exponential generating functions and
Joyal's combinatorial species.

\subsection{Contributions}
\begin{enumerate}
\item Clean definitions of order and degree valued in the completions $\Nbar$ and $\Nbot$,
with a complete API of extremal-characterisation lemmas (Section~\ref{sec:indices}).
\item The tropical inequalities for addition (Theorems~\ref{thm:ord-add}, \ref{thm:deg-add}).
\item Exact additivity of order and degree under the Cauchy convolution
(Theorems~\ref{thm:ord-conv}, \ref{thm:deg-conv}), via the unique-extremal-pair argument.
\item A corollary for combinatorial species: the extremal profile of a binomial
convolution, hence additivity of minimal structure sizes under structural product
(Section~\ref{sec:species}).
\end{enumerate}

\section{Setting and notation}
Throughout, $f, g \colon \N \to \Q$ denote \emph{finitely supported} rational sequences,
which one may picture as polynomials with rational coefficients. We write $f_n$ for the
value of $f$ at $n$ and $\supp(f) = \{ n \in \N : f_n \ne 0\}$ for its finite support.

We use two order-completions of $\N$: $\Nbar = \N \cup \{\top\}$ (a greatest element
adjoined) and $\Nbot = \N \cup \{\bot\}$ (a least element adjoined). Both carry the total
order extending that of $\N$, the lattice operations $\min$ and $\max$, and an additive
monoid structure with absorbing top/bottom: $n + \top = \top$ and $n + \bot = \bot$.

\section{Extremal-support indices}\label{sec:indices}

\subsection{Definitions}
\begin{definition}[Order / valuation]
The \emph{order} of $f$ is $\ord f = \min \supp(f) \in \Nbar$, with $\ord 0 = \top$.
\end{definition}

\begin{definition}[Degree]
The \emph{degree} of $f$ is $\deg f = \max \supp(f) \in \Nbot$, with $\deg 0 = \bot$.
\end{definition}

The conventions $\ord 0 = \top$ and $\deg 0 = \bot$ arise from min/max over the empty set
in a bounded lattice and are exactly what make the convolution laws hold without exception.

\subsection{Basic support API}
\begin{lemma}[Order is a lower bound]\label{lem:ord-lb}
If $f_n \ne 0$ then $\ord f \le n$.
\end{lemma}
\begin{proof}
$n \in \supp(f)$, and the minimum of a finite set is $\le$ any element.
\end{proof}

\begin{lemma}[Degree is an upper bound]\label{lem:deg-ub}
If $f_n \ne 0$ then $n \le \deg f$.
\end{lemma}
\begin{proof}
Dual to Lemma~\ref{lem:ord-lb}.
\end{proof}

\begin{lemma}[Vanishing below the order]
If $n < \ord f$ then $f_n = 0$. (Contrapositive of Lemma~\ref{lem:ord-lb}.)
\end{lemma}

\begin{lemma}[Vanishing above the degree]
If $\deg f < n$ then $f_n = 0$. (Contrapositive of Lemma~\ref{lem:deg-ub}.)
\end{lemma}

\begin{lemma}[The extremal indices are occupied]
If $\ord f = n \in \N$ then $f_n \ne 0$; if $\deg f = n$ then $f_n \ne 0$.
\end{lemma}
\begin{proof}
The minimum (resp. maximum) of a nonempty finite set is a member of that set, hence lies
in $\supp(f)$.
\end{proof}

\begin{lemma}[Realisation]
If $f \ne 0$ there exists $n$ with $\ord f = n$ and $f_n \ne 0$, and similarly there
exists $m$ with $\deg f = m$ and $f_m \ne 0$.
\end{lemma}
\begin{proof}
The support is finite and nonempty, hence has both a least and a greatest element, each of
which is occupied.
\end{proof}

\subsection{Extremal characterisations (the workhorses)}
\begin{lemma}[Characterisation of order]\label{lem:ord-char}
If $f_n \ne 0$ and $f_m = 0$ for all $m < n$, then $\ord f = n$.
\end{lemma}
\begin{proof}
$\le$: Lemma~\ref{lem:ord-lb}. $\ge$: every element of $\supp(f)$ is $\ge n$ because
indices below $n$ vanish; hence the minimum is $\ge n$. Antisymmetry gives equality.
\end{proof}

\begin{lemma}[Characterisation of degree]\label{lem:deg-char}
If $f_n \ne 0$ and $f_m = 0$ for all $m > n$, then $\deg f = n$. (Dual to
Lemma~\ref{lem:ord-char}.)
\end{lemma}

\section{The tropical laws for addition}

\begin{theorem}[Order is min-superadditive]\label{thm:ord-add}
For all $f, g$, $\quad \min(\ord f, \ord g) \le \ord(f + g)$.
\end{theorem}
\begin{proof}
If $(f+g)_n \ne 0$ then $f_n \ne 0$ or $g_n \ne 0$, so by Lemma~\ref{lem:ord-lb}
$\ord f \le n$ or $\ord g \le n$; in either case $\min(\ord f, \ord g) \le n$. As this
holds for every index in $\supp(f+g)$, it holds for the minimum of that support, namely
$\ord(f+g)$. Boundary cases with a zero summand are absorbed by $\top$.
\end{proof}

\begin{theorem}[Degree is max-subadditive]\label{thm:deg-add}
For all $f, g$, $\quad \deg(f + g) \le \max(\deg f, \deg g)$. (Dual to
Theorem~\ref{thm:ord-add}.)
\end{theorem}

\begin{remark}[Strictness]
Both inequalities can be strict: for $f = x^9$, $g = x^3 - x^9$ one has
$\deg(f+g) = 3 < 9$. Nonarchimedean theory predicts equality whenever the extremal
indices differ (Conjecture~\ref{conj:C1}).
\end{remark}

\section{The finitely supported Cauchy convolution}

\begin{definition}[Cauchy convolution coefficient]
For $f, g$ and $n \in \N$,
\[
(f * g)_n \;=\; \sum_{i=0}^{n} f_i \, g_{n-i} \;=\; \sum_{i+j=n} f_i\, g_j .
\]
\end{definition}

\begin{lemma}[Support bound]\label{lem:supp-bound}
$(f * g)_n \ne 0$ implies $n \le \sup \supp(f) + \sup \supp(g)$.
\end{lemma}
\begin{proof}
If $n$ exceeds that bound, then in every split $i + j = n$ either $i > \sup\supp(f)$ (so
$f_i = 0$) or $j > \sup\supp(g)$ (so $g_j = 0$); every summand vanishes.
\end{proof}

Lemma~\ref{lem:supp-bound} shows $n \mapsto (f*g)_n$ has finite support, so it is a
genuine finitely supported sequence $f * g$, the Cauchy product of the corresponding
polynomials. We have $0 * g = 0$ and $f * 0 = 0$.

\section{Exact additivity under convolution}

\begin{theorem}[Order is exactly additive]\label{thm:ord-conv}
For all $f, g$, $\quad \ord(f * g) = \ord f + \ord g$ in $\Nbar$ (with $n + \top = \top$).
\end{theorem}
\begin{proof}
If $f = 0$ or $g = 0$ both sides are $\top$. Otherwise let $a = \ord f$, $b = \ord g$ with
$f_a \ne 0$, $g_b \ne 0$, $f_i = 0$ for $i < a$, $g_j = 0$ for $j < b$. Apply
Lemma~\ref{lem:ord-char} at $n = a + b$.

\emph{The coefficient at $a+b$ is nonzero.} In $(f*g)_{a+b} = \sum_{i+j=a+b} f_i g_j$, if
$i < a$ then $f_i = 0$; if $i > a$ then $j = a+b-i < b$, so $g_j = 0$. The only surviving
split is the unique extremal pair $(a, b)$, giving $(f*g)_{a+b} = f_a g_b$. Since $\Q$ is
an integral domain and $f_a, g_b \ne 0$, this product is nonzero.

\emph{All lower coefficients vanish.} For $n < a+b$ and any split $i+j=n$, we cannot have
both $i \ge a$ and $j \ge b$; hence $f_i = 0$ or $g_j = 0$, so $(f*g)_n = 0$.

By Lemma~\ref{lem:ord-char}, $\ord(f * g) = a + b = \ord f + \ord g$.
\end{proof}

\begin{theorem}[Degree is exactly additive]\label{thm:deg-conv}
For all $f, g$, $\quad \deg(f * g) = \deg f + \deg g$ in $\Nbot$ (with $n + \bot = \bot$).
\end{theorem}
\begin{proof}
Dual to Theorem~\ref{thm:ord-conv}. With $f, g \ne 0$ and $a = \deg f$, $b = \deg g$, the
unique surviving split of the index $a+b$ is $(a, b)$, so $(f*g)_{a+b} = f_a g_b \ne 0$ by
integrality, while $(f*g)_n = 0$ for $n > a+b$. Apply Lemma~\ref{lem:deg-char}.
\end{proof}

\begin{corollary}[Tropical homomorphism]
The map $f \mapsto (\ord f, \deg f)$ sends convolution to coordinatewise addition and
addition to $(\ge \min, \le \max)$. Thus $\ord$ is a lax homomorphism into the tropical
min-plus semiring $(\Nbar, \min, +)$ --- exact on multiplication, super-additive on
addition --- and $\deg$ is its order-reversed max-plus counterpart.
\end{corollary}

\section{Downstream corollary: combinatorial species and EGFs}\label{sec:species}

\subsection{The species bridge}
To a counting sequence $a \colon \N \to \Q$ (e.g. $a_n = |F[n]|$, the number of
$F$-structures on $n$ labels) one associates the exponential generating function
$\EGF(a) = \sum_{n \ge 0} \frac{a_n}{n!} x^n$. Joyal's product of species corresponds, on
counting sequences, to the \emph{binomial convolution}
\[
(a \star b)_n \;=\; \sum_{i=0}^{n} \binom{n}{i} a_i\, b_{n-i},
\]
and the bridge theorem states $\EGF(a \star b) = \EGF(a)\cdot \EGF(b)$.

\subsection{The extremal profile of a binomial convolution}
The order of a counting sequence is the smallest size at which a structure exists. The
binomial convolution differs from the Cauchy convolution only by the strictly positive
weights $\binom{n}{i}$, which do not change which splits contribute at the extremal index.

\begin{corollary}[Binomial-convolution extremal profile]\label{cor:binconv}
For finitely supported $a, b$,
\[
\ord(a \star b) = \ord a + \ord b, \qquad \deg(a \star b) = \deg a + \deg b .
\]
\end{corollary}
\begin{proof}
At $n = \ord a + \ord b$ the only surviving split is $(\ord a, \ord b)$, contributing
$\binom{n}{\ord a}\, a_{\ord a}\, b_{\ord b}$. The binomial coefficient is a positive
integer, both factors are nonzero, and $\Q$ is a domain, so the product is nonzero; lower
coefficients vanish as in Theorem~\ref{thm:ord-conv}. The degree statement is dual.
\end{proof}

\subsection{Combinatorial meaning}
Corollary~\ref{cor:binconv} says the minimal size of a structure for the product species
$F \cdot G$ is the sum of the minimal sizes for $F$ and $G$, and such a minimal structure
exists: partition $\ord a + \ord b$ labels into compatible blocks
($\binom{\ord a + \ord b}{\ord a} > 0$ ways) and place the minimal $F$- and $G$-structures.
The degree statement gives the largest size at which the product species has any structure.

\section{Discussion and future work}

\begin{conjecture}[Sharp ultrametric equality]\label{conj:C1}
If $\ord f \ne \ord g$ then $\ord(f + g) = \min(\ord f, \ord g)$ (dually for $\deg$). This
upgrades $\ord$ to an exact tropical valuation off the diagonal $\ord f = \ord g$.
\end{conjecture}

\begin{conjecture}[Composition is tropically multiplicative]
If $g$ has order $\ge 1$ (vanishing constant term), then
$\ord(f \circ g) = \ord f \cdot \ord g$ (with $n \cdot \top = \top$ for $n \ne 0$). For
species, $\ord(F \circ G) = \ord F \cdot \ord G$: the minimal size of a composite is the
product of minimal sizes, extending the bridge to the plethystic operator.
\end{conjecture}

\begin{conjecture}[Prime-indexed valuation profile]
Each prime $p$ supplies a further valuation $n \mapsto v_p(a_n)$, assembling into a
multi-place profile $(v_x, (v_p)_p)$. For the species of sets ($a_n \equiv 1$) every
$p$-adic profile is flat zero; for cyclic orders ($a_n = (n-1)!$) the profile obeys the
Legendre / lifting-the-exponent law $v_p((n-1)!) = \frac{(n-1) - s_p(n-1)}{p-1}$, where
$s_p$ is the base-$p$ digit sum.
\end{conjecture}

\section{Conclusion}
From the most elementary invariants of a sequence --- where it starts and where it stops
--- we isolated the tropical arithmetic those invariants obey: relaxed (inequalities)
under addition because of cancellation, exact (equalities) under convolution because of
the unique extremal contributing pair and the absence of zero-divisors. Transported across
the exponential-generating-function bridge, the order law becomes the statement that
minimal structure sizes add under the product of combinatorial species. Valuation theory,
tropical algebra, and enumerative combinatorics describe one and the same phenomenon, and
the dictionary between them is exact wherever multiplication is in play.

\end{document}

