function EXTREMAL_INDICES(f):
    keys <- [ n for (n, c) in f if c != 0 ]
    if keys is empty:
        return (+inf, -inf)            # ord 0 = top, deg 0 = bot
    return (min(keys), max(keys))       # (ord f, deg f)

function CAUCHY_CONVOLUTION(f, g):
    out <- empty map
    for (i, a) in f with a != 0:
        for (j, b) in g with b != 0:
            out[i + j] <- out[i + j] + a * b
    return { n : c in out if c != 0 }

